package com.immortal.mediabufferfixture;
import android.app.Activity;
import android.content.Context;
import android.content.ContextWrapper;
import android.content.SharedPreferences;
import android.media.MediaMetadata;
import android.media.session.MediaController;
import android.media.session.MediaSession;
import android.media.session.PlaybackState;
import android.os.*;
import dalvik.system.DexClassLoader;
import org.json.JSONArray;
import org.json.JSONObject;
import java.io.*;
import java.lang.reflect.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public final class MediaBufferActivity extends Activity {
 private final Handler owner=new Handler(Looper.getMainLooper());private final JSONArray cases=new JSONArray();
 private final List<MediaSession> sessions=new ArrayList<>();private final AtomicInteger prefRequests=new AtomicInteger();
 private HandlerThread callbackThread;private Handler callbackHandler;private Context isolated;private File source;private boolean closed;private int failures,released;
 private Object reader;private Method select,snapshot,playPause;private Field active,started,lastToken;private Object originalActive,originalToken;
 private static final String OWN="com.immortal.launcher.debug";
 private interface Case {void run()throws Exception;}
 public void onCreate(Bundle b){super.onCreate(b);owner.postDelayed(()->finishReport("owner_timeout"),30000);new Thread(this::probe,"OwnedMediaBuffer").start();}
 private void probe(){try{
  source=new File(getCacheDir(),"source.apk");try(InputStream in=getAssets().open("source.apk");OutputStream out=new FileOutputStream(source)){byte[] b=new byte[65536];for(int n;(n=in.read(b))!=-1;)out.write(b,0,n);}
  DexClassLoader loader=new DexClassLoader(source.getAbsolutePath(),getCodeCacheDir().getAbsolutePath(),null,getClassLoader().getParent());Class<?> type=loader.loadClass("com.immortal.launcher.MediaSessionReader");check(type.getClassLoader()==loader,"Actual embedded reader class loader");reader=type.getField("INSTANCE").get(null);
  for(Method m:type.getDeclaredMethods()){Class<?>[] p=m.getParameterTypes();if(m.getName().startsWith("selectSession")&&p.length==3&&p[0]==List.class&&p[1]==String.class&&p[2]==MediaSession.Token.class){check(select==null,"Unique selectSession signature");select=m;}if(m.getName().startsWith("snapshotFrom")&&p.length==1&&p[0].getName().equals("com.immortal.launcher.MediaSessionReader$SelectedSession")){check(snapshot==null,"Unique selected snapshot signature");snapshot=m;}}
  check(select!=null&&snapshot!=null,"Actual selectSession and captured snapshot available");select.setAccessible(true);snapshot.setAccessible(true);playPause=type.getMethod("playPause");active=type.getDeclaredField("active");active.setAccessible(true);started=type.getDeclaredField("started");started.setAccessible(true);lastToken=type.getDeclaredField("lastPlayingToken");lastToken.setAccessible(true);originalActive=active.get(null);originalToken=lastToken.get(null);check(originalActive==null&&originalToken==null&&!started.getBoolean(null),"Loaded isolated reader dormant");
  isolated=new ContextWrapper(this){public SharedPreferences getSharedPreferences(String name,int mode){prefRequests.incrementAndGet();throw new IllegalStateException("Preference access forbidden");}public Context getApplicationContext(){return this;}};
  callbackThread=new HandlerThread("OwnedMediaCallbacks");callbackThread.start();callbackHandler=new Handler(callbackThread.getLooper());
  runCase("previousPlayingBufferRetainedWithSnapshot",()->{MediaSession a=session("a");MediaController c=controller(a);MediaSession.Token prior=previousPlaying(a,c);state(a,PlaybackState.STATE_BUFFERING,1234);Object chosen=pick(Collections.singletonList(c),prior);check(chosen!=null&&selectedController(chosen).getSessionToken().equals(prior),"Previous actually-playing buffer retained");checkSnapshot(snapshot.invoke(reader,chosen),"PLAYING",1234,prior);});
  runCase("previousBufferSurvivesUnrelatedPausedSession",()->{MediaSession a=session("a"),b=session("b");MediaController ca=controller(a),cb=controller(b);MediaSession.Token prior=previousPlaying(a,ca);state(a,PlaybackState.STATE_BUFFERING,1234);state(b,PlaybackState.STATE_PAUSED,2222);Object chosen=pick(Arrays.asList(cb,ca),prior);check(chosen!=null&&selectedController(chosen).getSessionToken().equals(prior),"Previous buffer survives never-playing paused competitor");});
  runCase("neverPlayedBufferIgnored",()->{MediaSession a=session("a");state(a,PlaybackState.STATE_BUFFERING,1234);check(pick(Collections.singletonList(controller(a)),null)==null,"Buffer without playing history ignored");});
  runCase("differentPreviousTokenCannotAdmitBuffer",()->{MediaSession a=session("a"),b=session("b");MediaController ca=controller(a);MediaSession.Token other=previousPlaying(b,controller(b));state(a,PlaybackState.STATE_BUFFERING,1234);check(pick(Collections.singletonList(ca),other)==null,"Nonmatching previous token ignored");});
  runCase("actualPlayingWinsOverPreviousBuffer",()->{MediaSession a=session("a"),b=session("b");MediaController ca=controller(a),cb=controller(b);MediaSession.Token prior=previousPlaying(a,ca);state(a,PlaybackState.STATE_BUFFERING,1234);state(b,PlaybackState.STATE_PLAYING,2222);Object chosen=pick(Arrays.asList(ca,cb),prior);check(chosen!=null&&selectedController(chosen).getSessionToken().equals(cb.getSessionToken()),"Actual playing wins");});
  runCase("previousPausedStillRetained",()->{MediaSession a=session("a");MediaController c=controller(a);MediaSession.Token prior=previousPlaying(a,c);state(a,PlaybackState.STATE_PAUSED,1234);Object chosen=pick(Collections.singletonList(c),prior);check(chosen!=null,"Previous paused session retained");checkSnapshot(snapshot.invoke(reader,chosen),"PAUSED",1234,prior);});
  runCase("previousStoppedRemainsIgnored",()->{MediaSession a=session("a");MediaController c=controller(a);MediaSession.Token prior=previousPlaying(a,c);state(a,PlaybackState.STATE_STOPPED,1234);check(pick(Collections.singletonList(c),prior)==null,"Previous stopped ignored");});
  runCase("capturedBufferSnapshotRetainsSelectedState",()->{MediaSession a=session("a");MediaController c=controller(a);MediaSession.Token prior=previousPlaying(a,c);state(a,PlaybackState.STATE_BUFFERING,1234);Object chosen=pick(Collections.singletonList(c),prior);check(chosen!=null,"Captured buffer selection exists");state(a,PlaybackState.STATE_PAUSED,9876);check(c.getPlaybackState().getState()==PlaybackState.STATE_PAUSED,"Controller now paused");checkSnapshot(snapshot.invoke(reader,chosen),"PLAYING",1234,prior);});
  runCase("bufferingPlayPauseDispatchesPause",()->transport(PlaybackState.STATE_BUFFERING,true));
  runCase("pausedPlayPauseDispatchesPlay",()->transport(PlaybackState.STATE_PAUSED,false));
  check(!started.getBoolean(null)&&lastToken.get(null)==originalToken,"Reader listener/history not started or mutated");active.set(null,originalActive);finishReport(null);
 }catch(Throwable t){finishReport("setup:"+describe(t));}}
 private void runCase(String name,Case body)throws Exception {String error=null;try{body.run();}catch(Throwable t){error=describe(t);}finally{if(active!=null)active.set(null,originalActive);}boolean pass=error==null;if(!pass)failures++;cases.put(new JSONObject().put("name",name).put("passed",pass).put("error",error==null?JSONObject.NULL:error).put("readerDormant",started!=null&&!started.getBoolean(null)).put("unexpectedPreferenceRequests",prefRequests.get()));}
 private MediaSession session(String tag){MediaSession s=new MediaSession(isolated,"generated-"+tag+"-"+sessions.size());s.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,"Generated track").putString(MediaMetadata.METADATA_KEY_ARTIST,"Fixture only").putString(MediaMetadata.METADATA_KEY_MEDIA_ID,"generated-track-id").putLong(MediaMetadata.METADATA_KEY_DURATION,120000).build());sessions.add(s);return s;}
 private MediaController controller(MediaSession s){return new MediaController(isolated,s.getSessionToken());}
 private void state(MediaSession s,int value,long position){s.setPlaybackState(new PlaybackState.Builder().setState(value,position,1f,SystemClock.elapsedRealtime()).setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_SEEK_TO).build());}
 private MediaSession.Token previousPlaying(MediaSession s,MediaController c)throws Exception {state(s,PlaybackState.STATE_PLAYING,1234);Object chosen=pick(Collections.singletonList(c),null);check(chosen!=null&&selectedController(chosen).getSessionToken().equals(c.getSessionToken()),"Actual prior playing selected");return c.getSessionToken();}
 private Object pick(List<MediaController> values,MediaSession.Token prior)throws Exception {return select.invoke(reader,values,OWN,prior);}
 private MediaController selectedController(Object selected)throws Exception{return (MediaController)selected.getClass().getMethod("getController").invoke(selected);}
 private void checkSnapshot(Object value,String state,long position,MediaSession.Token token)throws Exception {Class<?> c=value.getClass();check(c.getMethod("getState").invoke(value).toString().equals(state),"Snapshot state "+state);check(c.getMethod("getTitle").invoke(value).equals("Generated track")&&c.getMethod("getArtist").invoke(value).equals("Fixture only")&&c.getMethod("getMediaId").invoke(value).equals("generated-track-id"),"Literal generated metadata retained");check(((Number)c.getMethod("getPositionMs").invoke(value)).longValue()==position&&((Number)c.getMethod("getDurationMs").invoke(value)).longValue()==120000,"Snapshot position/duration retained");check(token.equals(c.getMethod("getSessionToken").invoke(value))&&c.getMethod("getCanSeek").invoke(value).equals(true),"Snapshot token/seek retained");}
 private void transport(int state,boolean pause)throws Exception {MediaSession s=session("transport");MediaController c=controller(s);AtomicInteger plays=new AtomicInteger(),pauses=new AtomicInteger();CountDownLatch delivered=new CountDownLatch(1);s.setCallback(new MediaSession.Callback(){public void onPlay(){plays.incrementAndGet();delivered.countDown();}public void onPause(){pauses.incrementAndGet();delivered.countDown();}},callbackHandler);state(s,state,1234);active.set(null,c);try{playPause.invoke(reader);check(delivered.await(3,TimeUnit.SECONDS),"Owned real session transport callback delivered");CountDownLatch barrier=new CountDownLatch(1);callbackHandler.post(barrier::countDown);check(barrier.await(3,TimeUnit.SECONDS),"Owned callback queue drained");check(plays.get()==(pause?0:1)&&pauses.get()==(pause?1:0),"Expected play="+(pause?0:1)+" pause="+(pause?1:0)+"; observed play="+plays.get()+" pause="+pauses.get());}finally{active.set(null,originalActive);s.setCallback(null);}}
 private static void check(boolean condition,String message){if(!condition)throw new AssertionError(message);}
 private static String describe(Throwable t){if(t instanceof InvocationTargetException&&((InvocationTargetException)t).getCause()!=null)t=((InvocationTargetException)t).getCause();return t.getClass().getName()+":"+String.valueOf(t.getMessage());}
 private static String digest(File file)throws Exception{MessageDigest md=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] b=new byte[65536];for(int n;(n=in.read(b))!=-1;)md.update(b,0,n);}StringBuilder result=new StringBuilder();for(byte b:md.digest())result.append(String.format(Locale.US,"%02x",b&255));return result.toString();}
 private synchronized void finishReport(String error){if(closed)return;closed=true;owner.removeCallbacksAndMessages(null);boolean activeRestored=false,historyUnchanged=false,threadRetired=false;try{if(active!=null){active.set(null,originalActive);activeRestored=active.get(null)==originalActive;}historyUnchanged=lastToken!=null&&lastToken.get(null)==originalToken;}catch(Exception ignored){}for(MediaSession s:sessions)try{s.setCallback(null);s.release();released++;}catch(Exception ignored){}if(callbackThread!=null){callbackThread.quitSafely();try{callbackThread.join(1500);}catch(InterruptedException ignored){}threadRetired=!callbackThread.isAlive();}try{JSONObject report=new JSONObject().put("ok",error==null&&cases.length()==10&&failures==0&&prefRequests.get()==0&&activeRestored&&historyUnchanged&&threadRetired&&released==sessions.size()).put("error",error==null?JSONObject.NULL:error).put("tests",cases.length()).put("failures",failures).put("cases",cases).put("sourceSha256",source==null?JSONObject.NULL:digest(source)).put("sourceBytes",source==null?0:source.length()).put("sdk",android.os.Build.VERSION.SDK_INT).put("actualEmbeddedApkClassLoader",reader!=null).put("actualSelectSessionCapturedSnapshotAndPlayPause",select!=null&&snapshot!=null&&playPause!=null).put("selectMethod",select==null?JSONObject.NULL:select.getName()).put("snapshotMethod",snapshot==null?JSONObject.NULL:snapshot.getName()).put("fixturePackage",getPackageName()).put("internetPermission",checkSelfPermission("android.permission.INTERNET")==0).put("unexpectedPreferenceRequests",prefRequests.get()).put("ownedSessionsCreated",sessions.size()).put("ownedSessionsReleased",released).put("callbackThreadRetired",threadRetired).put("activeControllerRestored",activeRestored).put("historyTokenUnchanged",historyUnchanged).put("scope","Actual debug APK helper selection/captured snapshot/transport through fixture-owned real MediaSession/MediaController; generated metadata, no audio playback, notification listener, owner preferences, provider, network, UI, optimized/API28 or cross-package relay-priority acceptance");try(OutputStream out=new FileOutputStream(new File(getExternalFilesDir(null),"report.json"))){out.write(report.toString(2).getBytes("UTF-8"));}}catch(Exception ignored){}runOnUiThread(this::finish);}
 protected void onDestroy(){if(!closed)finishReport("owner_destroyed");super.onDestroy();}
}
